/* Shared, validated interior maps. */
(function(root){
const KEY='minitman-fps-level-v1';
function defaults(){return Array.from({length:7},(_,level)=>{const map=Array.from({length:19},(_,z)=>Array.from({length:23},(_,x)=>x===0||x===22||z===0||z===18?1:0));for(const [x,z,type]of [[6,7,2],[16,11,2],[15,6,3],[7,12,3],[5,10,4],[17,8,4]]){map[z+level%2][x]=type;if(type>=3)map[z+level%2][x+1]=type;}return map;});}
function structure(){return {stairs:Array.from({length:6},(_,n)=>n%2?{x:3,z:3}:{x:19,z:15}),roof:{x:3,z:2},entry:{x:3,z:3},side:{x:3,z:6},sideEntry:{x:2,z:6},computer:{x:19,z:15}};}
function points(level,data){const st=data?.structure||structure(),p=[];if(level===0)p.push({...st.roof,label:'Entrée / sortie toit',id:'roof'});if(level>0)p.push({...st.stairs[level-1],label:'Escalier ↑',id:'stairs',index:level-1});if(level<6)p.push({...st.stairs[level],label:'Escalier ↓',id:'stairs',index:level});if(level===2)p.push({...st.side,label:'Entrée / sortie porte',id:'side'});if(level===6)p.push({...st.computer,label:'Ordinateur',id:'computer'});return p;}
function protectedCells(level,data){const cells=new Map();for(const p of [...points(level,data),...(level===0?[{...(data?.structure||structure()).entry}]:level===2?[{...(data?.structure||structure()).sideEntry}]:[])])for(const dx of [-1,0])for(const dz of [-1,0])cells.set((p.z+dz)+','+(p.x+dx),{x:p.x+dx,z:p.z+dz});return [...cells.values()];}
function validate(value){if(![1,2].includes(value?.version)||!Array.isArray(value.maps)||value.maps.length!==7)throw Error('Le fichier doit contenir 7 étages.');const result=JSON.parse(JSON.stringify(value));result.structure??=structure();result.version=2;const st=result.structure;syncEntries(result);if(!Array.isArray(st.stairs)||st.stairs.length!==6)throw Error('Six escaliers sont nécessaires.');st.stairs.forEach(p=>p.surface='wall');result.maps.forEach((map,level)=>{const h=map?.length,w=map?.[0]?.length;if(!Array.isArray(map)||h<10||h>2048||w<10||w>2048||map.some(row=>!Array.isArray(row)||row.length!==w||row.some(v=>!Number.isInteger(v)||v<0||v>4)))throw Error('Grille invalide à l’étage '+(level+1));for(let z=0;z<h;z++)for(let x=0;x<w;x++)if((x===0||x===w-1||z===0||z===h-1)&&map[z][x]!==1)throw Error('Les murs extérieurs doivent rester fermés.');const p=[...points(level,result),...(level===0?[st.entry]:level===2?[st.sideEntry]:[])];if(p.some(t=>t.surface&&!['wall','ceiling'].includes(t.surface)))throw Error('Surface d’accès invalide.');const entry=level?st.stairs[level-1]:st.entry,target=level<6?st.stairs[level]:st.computer;if(Math.hypot(target.x-entry.x,target.z-entry.z)<2)throw Error('Écartez les accès de montée et descente à l’étage '+(level+1));if(p.some(t=>!Number.isInteger(t.x)||!Number.isInteger(t.z)||t.x<2||t.z<2||t.x>=w-1||t.z>=h-1))throw Error('Accès hors de la grille à l’étage '+(level+1));if(protectedCells(level,result).some(t=>map[t.z]?.[t.x]!==0))throw Error('Un accès est bloqué à l’étage '+(level+1));const start=p[0],queue=[[start.x,start.z]],seen=new Set([start.z*w+start.x]);for(let i=0;i<queue.length;i++){const [x,z]=queue[i];for(const [dx,dz]of [[1,0],[-1,0],[0,1],[0,-1]]){const nx=x+dx,nz=z+dz,k=nz*w+nx;if(map[nz]?.[nx]===0&&!seen.has(k)){seen.add(k);queue.push([nx,nz]);}}}if(p.some(t=>!seen.has(t.z*w+t.x)))throw Error('Les accès ne sont plus reliés à l’étage '+(level+1));});return result;}
function load(storage){try{const text=storage?.getItem(KEY);if(text)return validate(JSON.parse(text));}catch{}return {version:2,maps:defaults(),structure:structure()};}
function spawn(map,access,preferred){const candidates=[preferred,{x:access.x+1,z:access.z},{x:access.x,z:access.z-1},{x:access.x,z:access.z+1},{x:access.x-1,z:access.z},access];return candidates.find(p=>[-1,0].every(dx=>[-1,0].every(dz=>map[p.z+dz]?.[p.x+dx]===0)))||{x:access.x,z:access.z};}
function syncEntries(data){const st=data.structure;st.entry=spawn(data.maps[0],st.roof,{x:st.roof.x,z:st.roof.z+1});st.sideEntry=spawn(data.maps[2],st.side,{x:st.side.x-1,z:st.side.z});}
function surface(point){return point.id==="stairs"?"wall":point.surface||(["roof","entry"].includes(point.id)?"ceiling":"wall");}
function moveAccess(data,point,x,z){const copy=JSON.parse(JSON.stringify(data));const shift=expand(copy,x,z);x+=shift.x;z+=shift.z;const target=point.id==='stairs'?copy.structure.stairs[point.index]:copy.structure[point.id],dx=x-target.x,dz=z-target.z;Object.assign(target,{x,z});syncEntries(copy);const levels=point.id==='stairs'?[point.index,point.index+1]:[point.id==='roof'||point.id==='entry'?0:point.id==='computer'?6:2];for(const n of levels){const map=copy.maps[n];for(const p of points(n,copy))if(p.x<2||p.z<2||p.x>=map[0].length-1||p.z>=map.length-1)throw Error('Accès hors de la grille d’un étage relié.');for(const p of protectedCells(n,copy))if(map[p.z]?.[p.x]!==0)throw Error('Le dégagement de l’accès est occupé.');}return copy;}
function expand(data,x,z){const sx=x<2?Math.ceil((2-x)/16)*16:0,sz=z<2?Math.ceil((2-z)/16)*16:0;data.maps=data.maps.map(old=>{const w=Math.max(old[0].length+sx,Math.ceil((x+sx+3)/16)*16),h=Math.max(old.length+sz,Math.ceil((z+sz+3)/16)*16);if(w===old[0].length&&h===old.length&&!sx&&!sz)return old;return Array.from({length:h},(_,b)=>Array.from({length:w},(_,a)=>a===0||b===0||a===w-1||b===h-1?1:old[b-sz]?.[a-sx]??0));});if(sx||sz){for(const p of [...data.structure.stairs,...['roof','entry','side','sideEntry','computer'].map(k=>data.structure[k])]){p.x+=sx;p.z+=sz;}}return {x:sx,z:sz};}
const api={KEY,defaults,structure,points,surface,expand,moveAccess,protectedCells,validate,load};if(typeof module!=='undefined')module.exports=api;else root.FpsLevel=api;
})(typeof window!=='undefined'?window:globalThis);
